def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (after '+')
        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split off pre-release (after '-')
        if '-' in v_without_build:
            parts = v_without_build.split('-', 1)
            version_part = parts[0]
            prerelease_part = parts[1]
        else:
            version_part = v_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        version_nums = tuple(map(int, version_part.split('.')))

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
            # Convert all-digit identifiers to integers, keep others as strings
            parsed_identifiers = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    parsed_identifiers.append((0, int(identifier)))
                else:
                    parsed_identifiers.append((1, identifier))
            prerelease_tuple = tuple(parsed_identifiers)
        else:
            prerelease_tuple = None

        return version_nums, prerelease_tuple

    def sort_key(item):
        index, version = item
        version_nums, prerelease_tuple = parse_version(version)

        # Versions without pre-release sort after versions with pre-release
        # So we use (version_nums, (1 if prerelease_tuple is None else 0, ...))
        if prerelease_tuple is None:
            return (version_nums, (1,), index)
        else:
            return (version_nums, (0, prerelease_tuple), index)

    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [v for _, v in sorted_versions]

